package com.campus.lostfound.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="audit_logs",indexes=@Index(columnList="createdAt")) public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) private User actor;@Column(nullable=false,length=80) private String action;@Column(nullable=false,length=180) private String target;@Column(nullable=false) private Instant createdAt=Instant.now();protected AuditLog(){}public AuditLog(User actor,String action,String target){this.actor=actor;this.action=action;this.target=target;}public UUID getId(){return id;}public User getActor(){return actor;}public String getAction(){return action;}public String getTarget(){return target;}public Instant getCreatedAt(){return createdAt;} }
